function getSaved(){try{let x=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');return x&&x.current?x:null}catch(_){return null}}
function clearSaved(){try{localStorage.removeItem(SAVE_KEY)}catch(_){}}
