  if(h.stage===1)showHintNotice(`<b>${tr('hintMove')} :</b> ${message.move}<br><span class="hint-secondary">${message.where}</span>`);
  else if(h.stage===2)showHintNotice(`<b>${tr('hintMove')} :</b> ${message.move}<br><b>${tr('hintWhy')} :</b> ${message.why}`);
