    let cell=patchPointToCell(e.clientX,e.clientY,b);if(!cell)return;
    if(cell[0]===drag.end[0]&&cell[1]===drag.end[1])return;
    drag.end=cell;drag.moved=drag.moved||cell[0]!==drag.anchor[0]||cell[1]!==drag.anchor[1];
